WITH filtered AS (SELECT *, CEIL(quantity) quantity_whole FROM order_items WHERE unit_price <= 300), enriched AS (SELECT a.*, d.price, d.category, d.brand FROM filtered a LEFT JOIN products d ON a.product_id = d.id), enriched_order_items AS (SELECT src.*, p.amount FROM enriched src JOIN orders p ON src.order_id = p.id), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, category ORDER BY price DESC NULLS LAST, id) AS rn FROM enriched_order_items) ranked WHERE rn = 1), deduped_order_items AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY brand ORDER BY rn) AS rank_in_group FROM deduped) x WHERE rank_in_group = 1), metrics AS (SELECT *, LAG(quantity_whole, 1) OVER (PARTITION BY product_id ORDER BY unit_price, id) prev_quantity_whole, SUM(amount) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount, LAG(quantity_whole, 2) OVER (PARTITION BY product_id ORDER BY rank_in_group, id) prev_quantity_whole_2, NTILE(3) OVER (ORDER BY price, id) price_bucket FROM deduped_order_items) SELECT CASE WHEN prev_quantity_whole >= 76 THEN 'LARGE' ELSE 'SMALL' END AS prev_quantity_whole_tier, CASE WHEN unit_price >= 400 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, order_id, COUNT(*) FILTER (WHERE brand = 'Initech') AS initech_rows, MAX(quantity_whole) AS max_quantity_whole, COUNT_IF(category = 'Sports') AS sports_events, ROUND(AVG(price), 2) AS avg_price, MIN(unit_price) AS min_unit_price, COUNT(CASE WHEN brand = 'Globex' THEN 1 END) AS globex_count FROM metrics GROUP BY CASE WHEN prev_quantity_whole >= 76 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN unit_price >= 400 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id
